import { When, Then } from '@cucumber/cucumber';
import { strict as assert } from 'node:assert';
import {
  detectDownloadBrochureFiles,
  fillGenesisFieldsFromDataTable,
  setRetailOutlet,
  waitForDownloadBrochureFiles,
  waitForVisibleText,
} from '../support/genesisFormHelpers.js';

// Fill the form from the sheet loaded by 'the user has loaded the test data
// from the confluence page … and find the test data "<sheet>"' — the data
// lives in test-data/localTestData.js, same as the other forms.
When('I fill in all required fields from test data', async function () {
  const row = this.activeTestDataRow;
  assert.ok(
    row && Object.keys(row).length > 0,
    'No test data loaded — add a "the user has loaded the test data … find the test data …" step before filling the form',
  );
  this.genesisFilledData = await fillGenesisFieldsFromDataTable(this.page, row);
});

When('I set my retail outlet for postcode {string}', async function (postcode) {
  this.genesisRetailOutlet = await setRetailOutlet(this.page, postcode);
});

Then('I should see {string} success message', async function (param) {
  const visibility = await waitForVisibleText(this.page, param, 15000);
  if (visibility.visible) {
    assert.equal(visibility.visible, true, `Expected to see success message "${param}"`);
    return;
  }

  const isDownloadBrochure = /#downloadebrochure/i.test(this.page.url());
  if (isDownloadBrochure) {
    const selectedModel = this.genesisFilledData?.['Vehicle Selection'] || this.genesisFilledData?.['vehicle selection'] || '';
    const brochureFiles = await waitForDownloadBrochureFiles(this.page, selectedModel, 15000);
    assert.equal(
      brochureFiles.visible,
      true,
      `Expected brochure files for selected model "${selectedModel}", but found: ${brochureFiles.items.join(' | ')}`
    );
    return;
  }

  // Scroll to the form/status area so the screenshot captures any error message
  // that appears at the bottom of the form (e.g. "Sorry, something went wrong")
  await this.page.evaluate(() => {
    const statusEl = document.querySelector(
      '[class*="sorry"], [class*="error"], [class*="status"], [class*="wrong"], form#form-ryi-form, .cp-ryi__form'
    );
    if (statusEl) {
      statusEl.scrollIntoView({ behavior: 'instant', block: 'center' });
    } else {
      window.scrollTo(0, document.body.scrollHeight);
    }
  }).catch(() => {});
  await this.page.waitForTimeout(500);

  assert.equal(visibility.visible, true, `Expected to see success message "${param}"`);
});
